// Vérifier que le titre de l'inventaire affiche Products.
cy.get('[data-test="title"]').should('be.visible').and('have.text', 'Products');
// Vérifier qu'il y a exactement six produits et examiner chacun d'eux.
cy.get('.inventory_item').should('have.length', 6).each($product => {
  // Vérifier que le nom du produit est visible et non vide.
  cy.wrap($product).find('.inventory_item_name').should('be.visible').and('not.be.empty');
  // Vérifier que la description du produit est visible et non vide.
  cy.wrap($product).find('.inventory_item_desc').should('be.visible').and('not.be.empty');
  // Vérifier que le prix est visible et respecte le format monétaire à deux décimales.
  cy.wrap($product).find('.inventory_item_price').should('be.visible').and($price => {
    expect($price.text().trim()).to.match(/^\$\d+\.\d{2}$/);
  });
  // Vérifier que l'image du produit est visible et possède un src non vide.
  cy.wrap($product).find('img.inventory_item_img').should('be.visible').and('have.attr', 'src').and('not.be.empty');
  // Vérifier que le bouton Add to cart du produit est visible.
  cy.wrap($product).find('button[data-test^="add-to-cart"]').should('be.visible').and('contain.text', 'Add to cart');
});
